# Initially generated by GitHub Copilot.
"""Generate out/letter-small.txt from MAM-simple XML."""

import xml.etree.ElementTree as ET

from mb_cmn import file_io
from mb_misc import osis_book_abbrevs

_LETTER_SMALL_OUT_PATH = "out/letter-small.txt"


def write_letter_small_report(bkids):
    """Write all <letter-small> occurrences as BCV-qualified lines."""
    out_lines = list(_iter_letter_small_rows(bkids))
    out_text = "\n".join(out_lines)
    if out_text:
        out_text += "\n"
    file_io.with_tmp_openw(_LETTER_SMALL_OUT_PATH, {}, _write_text, out_text)
    print(f"Wrote {len(out_lines)} lines to {_LETTER_SMALL_OUT_PATH}")


def _iter_letter_small_rows(bkids):
    for bkg in osis_book_abbrevs.bk24_bkgs(bkids):
        bkg_name = bkg["bkg-name"]
        xml_path = f"../MAM-simple/out/xml-vtrad-mam/{bkg_name}.xml"
        tree = ET.parse(xml_path)
        root = tree.getroot()
        for book39 in root:
            if book39.tag != "book39":
                continue
            for child in book39:
                if child.tag != "chapter":
                    continue
                for verse in child:
                    if verse.tag != "verse":
                        continue
                    bkid, chnu, vrnu = osis_book_abbrevs.get_bcv_from_osis_id(
                        verse.attrib["osisID"]
                    )
                    for small_el in verse.iter("letter-small"):
                        small_text = small_el.attrib["text"]
                        yield f"{bkid} {chnu}:{vrnu}\t<small>{small_text}</small>"


def _write_text(text, out_fp):
    out_fp.write(text)
